import { WfDetailService } from '../../workflow/center/wf-detail.service.js'
import { WfStartService } from '../../workflow/center/wf-start.service.js'
import { WfInstanceRow } from '../../workflow/runtime/wf-runtime.entity.js'
import { LEAVE_MODEL } from './leave-wf.handler.js'
import { Leave } from './leave.entity.js'

const caller = () => clsGet('principal')!

/**
 * Leave requests (see docs/design-notes.md#workflow): the caller's own rows, never deleted (their instances show them).
 * Not data-scoped: the list is the caller's (`user_id`, the owner `assertStartable` requires too) and
 * the detail follows the instance access rule, so an approver in another dept sees what they decide on.
 */
@Injectable()
export class LeaveService extends BaseCrudService<Leave> {
  constructor(
    txHost: TransactionHost<TransactionalAdapterTypeOrm>,
    private readonly starts: WfStartService,
    private readonly details: WfDetailService,
    private readonly attachments: OaAttachmentService,
  ) {
    super(txHost, Leave)
  }

  protected override filter(
    qb: SelectQueryBuilder<Leave>,
    { leaveKind, startAtFrom, startAtTo, createdAtFrom, createdAtTo }: LeaveQuery,
  ): SelectQueryBuilder<Leave> {
    qb.andWhere('t.user_id = :me', { me: caller().userId })
    if (leaveKind) qb.andWhere('t.leave_kind = :leaveKind', { leaveKind })
    if (startAtFrom)
      qb.andWhere('t.start_at >= :startAtFrom', { startAtFrom: new Date(startAtFrom) })
    if (startAtTo) qb.andWhere('t.start_at <= :startAtTo', { startAtTo: new Date(startAtTo) })
    if (createdAtFrom)
      qb.andWhere('t.created_at >= :createdAtFrom', { createdAtFrom: new Date(createdAtFrom) })
    if (createdAtTo)
      qb.andWhere('t.created_at <= :createdAtTo', { createdAtTo: new Date(createdAtTo) })
    return qb
  }

  /** 旧记录尚无附件列值，列表始终返回数组而不回写历史数据。 */
  override async page<F extends string>(
    query: PageParams<F>,
    columns?: Partial<Record<F, string>>,
  ) {
    const page = await super.page(query, columns)
    for (const row of page.items) row.attachmentIds ??= []
    return page
  }

  /**
   * The caller's own row, or one whose live instance they may see (the one rule:
   * `WfDetailService.canView`; see docs/design-notes.md#workflow); else 404.
   */
  override async get(id: number): Promise<Leave> {
    const row = await this.repo.findOneBy({ id })
    if (row) row.attachmentIds ??= []
    if (row?.userId === caller().userId) return row
    if (row?.instanceId && (await this.details.canView(row.instanceId))) return row
    throw new NotFoundException()
  }

  /**
   * The submit: saves the caller's request as a draft and starts process `leave` on it in the same
   * transaction (a start that fails leaves no row); answers the row, `in_review` with its instance.
   */
  submit(dto: LeaveCreate): Promise<Leave> {
    return this.txHost.withTransaction(async () => {
      const { userId, deptId } = caller()
      const { initiatorPicks = {}, ...values } = parseOr400(leaveCreate, dto)
      const row = this.repo.create({
        ...values,
        attachmentIds: values.attachmentIds ?? [],
        userId,
        deptId,
        state: 'draft',
        instanceId: null,
      })
      const { id } = await this.repo.save(row)
      await this.attachments.sync('leave', id, row.attachmentIds ?? [], [], userId)
      // 选人只交给流程引擎校验和保存，不混入业务单据列。
      await this.starts.start(userId, {
        modelKey: LEAVE_MODEL,
        businessKey: String(id),
        formValues: {},
        initiatorPicks,
      })
      return this.repo.findOneByOrFail({ id })
    })
  }

  /**
   * Edits the caller's request (locked) while it is a draft or sent back to them (they hold the pending
   * task of the process's `begin`; the resubmit reads the row again); not theirs → 404, otherwise 409.
   */
  override update(id: number, dto: LeaveUpdate): Promise<void> {
    const changes = parseOr400(leaveUpdate, dto)
    return this.txHost.withTransaction(async () => {
      const known = await this.repo.findOneBy({ id })
      if (known?.userId !== caller().userId) throw new NotFoundException()
      if (known.instanceId !== null) {
        // 引擎动作先锁实例再读业务单：编辑沿用同一顺序，避免退回重提与编辑互锁。
        const instance = await this.txHost.tx.getRepository(WfInstanceRow).findOne({
          where: { id: known.instanceId },
          lock: { mode: 'pessimistic_write' },
        })
        if (!instance) throw new BizError(Err.CONFLICT)
      }
      const row = await this.repo.findOne({ where: { id }, lock: { mode: 'pessimistic_write' } })
      if (row?.userId !== caller().userId) throw new NotFoundException()
      // 草稿被另一事务发起后不能倒过来持有业务锁再取实例锁，交由调用方刷新后重试。
      if (row.instanceId !== known.instanceId) throw new BizError(Err.CONFLICT)
      const sentBack = row.instanceId !== null && (await this.sentBack(row.instanceId))
      if (row.state !== 'draft' && !sentBack) throw new BizError(Err.CONFLICT)
      if (changes.startAt !== undefined || changes.endAt !== undefined)
        parseOr400(leaveCreate, {
          ...row,
          attachmentIds: row.attachmentIds ?? [],
          startAt: row.startAt.toISOString(),
          endAt: row.endAt.toISOString(),
          ...changes,
        })
      if (Object.keys(changes).length) await this.repo.update(id, changes)
      if (changes.attachmentIds !== undefined)
        await this.attachments.sync(
          'leave',
          id,
          changes.attachmentIds,
          row.attachmentIds ?? [],
          caller().userId,
        )
    })
  }

  /**
   * The caller holds the pending task of the begin node (the tree's root) of instance `instanceId`;
   * task, instance and version all of the caller's tenant.
   */
  private async sentBack(instanceId: number): Promise<boolean> {
    const tid = tenantId()
    const rows: unknown[] = await this.txHost.tx.query(
      // qw:include-deleted wf_version: a deleted version still runs the instances started on it
      `SELECT t.id FROM wf_task t
         JOIN wf_instance i ON i.id = t.instance_id AND i.deleted_at IS NULL AND i.tenant_id = ?
         JOIN wf_version v ON v.id = i.version_id AND v.tenant_id = ?
        WHERE t.instance_id = ? AND t.assignee_id = ? AND t.state = 'pending'
          AND t.deleted_at IS NULL AND t.node_id = v.tree_json ->> '$.id' AND t.tenant_id = ? FOR SHARE`,
      [tid, tid, instanceId, caller().userId, tid],
    )
    return rows.length > 0
  }
}
